from pathlib import Path
import json
tid='DEV-PRED-A2Z-R5P1-ASTRA-PREBUILD-START-20261008-N1E134'
roots=[Path.home()/'.local/state/prediction-project-executor',Path.home()/'.local/share/prediction-project-executor']
hits=[]
for root in roots:
    if not root.exists(): continue
    for p in root.rglob('*'):
        if tid in p.name and p.is_file():
            hits.append(p)
def clean(s): return str(s).replace('\n',' ').replace('\r',' ').replace('|','/')[:5000]
parts=[]
for p in hits[:20]:
    try: txt=p.read_text(errors='replace')
    except Exception as e: txt='READERR:'+repr(e)
    parts.append(str(p)+'::'+clean(txt))
print('ERROR_CLASS=R5P1_ASTRA_START_DIAG')
print('ERROR='+' || '.join(parts))
raise SystemExit(1)
